# Let's test various hypothesis for combining left and right

def hypothesis_and(left, right):
    """If equal and non-zero, keep value, else 0"""
    result = []
    for row in zip(left, right):
        res_row = []
        for c in zip(row[0], row[1]):
            if c[0] == c[1] and c[0] != 0:
                res_row.append(c[0])
            else:
                res_row.append(0)
        result.append(res_row)
    return result

def hypothesis_overlap(left, right):
    """Only keep where both have 3"""
    result = []
    for row in zip(left, right):
        res_row = []
        for c in zip(row[0], row[1]):
            if c[0] == 3 and c[1] == 3:
                res_row.append(3)
            else:
                res_row.append(0)
        result.append(res_row)
    return result

def hypothesis_ones(left, right):
    """If either is 1-like, output 0? Both 0 -> 0, both 3 -> 3? Different -> ?"""
    result = []
    for row in zip(left, right):
        res_row = []
        for c in zip(row[0], row[1]):
            if c[0] == 0 and c[1] == 0:
                res_row.append(0)
            elif c[0] == 3 and c[1] == 3:
                res_row.append(3)
            else:
                # Different values
                # Maybe 0 here?
                res_row.append(0)
        result.append(res_row)
    return result

print("AND (equal and non-zero):")
result = hypothesis_and(left, right)
for row in result:
    print(row)

print("\nOverlap (both 3):")
result = hypothesis_overlap(left, right)
for row in result:
    print(row)

print("\nBoth 0/Both 3 rule:")
result = hypothesis_ones(left, right)
for row in result:
    print(row)

